package com.seekora.api;

import com.seekora.account.AccountDtos.AccountResponse;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;
import java.time.Instant;
import java.util.List;
import java.util.UUID;

public final class ApiDtos {
    private ApiDtos() { }
    public record ChatRequest(@NotBlank @Size(max = 30000) String message, UUID conversationId) { }
    /**
     * @param answerMode   "ai" (generated by the configured model) or "extractive" (sentences copied from web pages)
     * @param searchStatus "used", "skipped" (not needed for this question) or "unavailable" (search failed)
     * @param notice       plain-language caveat about how this answer was produced; may be null
     */
    public record ChatResponse(UUID conversationId, String title, MessageDto userMessage,
                               MessageDto assistantMessage, List<SourceDto> sources, String answerMode,
                               String searchStatus, String notice) { }
    public record SourceDto(String title, String url, String excerpt) { }
    public record MessageDto(UUID id, String role, String content, Instant createdAt,
                             List<SourceDto> sources, String answerMode) { }
    /** {@code messages} is null (and therefore omitted from JSON) in list responses. */
    public record ConversationDto(UUID id, String title, Instant createdAt, Instant updatedAt,
                                  List<MessageDto> messages) { }
    public record CreateConversationRequest(@Size(max = 160) String title) { }
    public record SummaryRequest(@NotBlank @Size(max = 50000) String text,
                                 @Size(max = 500) String instruction) { }
    public record SummaryResponse(String summary) { }
    /** Non-secret runtime status for the UI. {@code account} is null when nobody is signed in. */
    public record StatusResponse(boolean aiConfigured, boolean aiRequired, String model, String provider,
                                 AccountResponse account) { }
}
